<!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="/assets/css/app.css"><title>دوره‌های تست</title></head><body><header><b>✓ آزمون‌یار</b><nav><a href="/dashboard">داشبورد</a><a href="/projects">پروژه‌ها</a><a href="/test-cases">سناریوها</a><a href="/test-runs">دوره‌ها</a><a href="/my-tasks">کارتابل</a></nav></header><main class="app"><span>برنامه‌ریزی تست</span><h1>دوره‌های تست</h1><p>برای نسخه‌ها و تست‌های رگرسیون، دوره‌های مستقل ایجاد کنید.</p><?php if(session('message')):?><div class="alert"><?=esc(session('message'))?></div><?php endif ?><?php if(session('error')):?><div class="alert error"><?=esc(session('error'))?></div><?php endif ?><section><h2>دورهٔ جدید</h2><form method="post" class="grid"><label>پروژه<select name="project_id" required><option value="">انتخاب کنید</option><?php foreach($projects as $p):?><option value="<?=$p['id']?>"><?=esc($p['name'])?></option><?php endforeach?></select></label><label>نام دوره<input name="name" required placeholder="رگرسیون نسخه 1.0"></label><button class="btn">ایجاد دوره</button></form></section><section><h2>گرید دوره‌ها</h2><table><tr><th>نام</th><th>پروژه</th><th>وضعیت</th></tr><?php foreach($runs as $r):?><tr><td><?=esc($r['name'])?></td><td><?=esc($r['project_name'])?></td><td><i><?=esc($r['status'])?></i></td></tr><?php endforeach?></table></section></main></body></html>
